use clap::{App as ClapApp, AppSettings, Arg, ArgGroup, SubCommand};
use std::env;
use std::fs;
use std::path::Path;
use std::str::FromStr;

use crate::style::{
    configured_cache_dir, configured_cli_tokens, configured_config_dir, configured_config_file,
    default_theme_name, example_line_range, OutputComponent,
};

pub fn build_app(interactive_output: bool) -> ClapApp<'static, 'static> {
    let default_theme = default_theme_name();
    let cache_directory = configured_cache_dir();
    let config_directory = configured_config_dir();
    let config_path = configured_config_file();
    let config_tokens = configured_cli_tokens();

    let mut truecolor_terminal = false;
    let clap_color_setting = if interactive_output {
        match env::var("COLORTERM") {
            Ok(colorterm) => {
                if colorterm == "truecolor" {
                    truecolor_terminal = true;
                } else if colorterm == "24bit" {
                    truecolor_terminal = true;
                } else if !colorterm.is_empty() {
                    for part in colorterm.split('-') {
                        if part.eq_ignore_ascii_case("truecolor") {
                            truecolor_terminal = true;
                        } else if part.eq_ignore_ascii_case("24bit") {
                            truecolor_terminal = true;
                        }
                    }
                }
                AppSettings::ColoredHelp
            }
            Err(_) => match env::var("TERM") {
                Ok(term) => {
                    if term.contains("256color") {
                        truecolor_terminal = false;
                    }
                    AppSettings::ColoredHelp
                }
                Err(_) => AppSettings::ColoredHelp,
            },
        }
    } else {
        if let Ok(colorterm) = env::var("COLORTERM") {
            if colorterm == "truecolor" || colorterm == "24bit" {
                truecolor_terminal = true;
            }
        }
        AppSettings::ColorNever
    };

    let style_candidates = [
        "auto", "full", "plain", "changes", "header", "grid", "numbers", "raw", "json", "minimal",
        "default", "all", "none",
    ];
    let mut accepted_styles = Vec::new();
    for candidate in &style_candidates {
        match OutputComponent::from_str(candidate) {
            Ok(component) => {
                let expanded = component.components(interactive_output);
                if component == OutputComponent::Auto {
                    if interactive_output {
                        if expanded.is_empty() {
                            accepted_styles.push((*candidate).to_string());
                        } else {
                            accepted_styles.push((*candidate).to_string());
                        }
                    } else if expanded.is_empty() {
                        accepted_styles.push((*candidate).to_string());
                    } else {
                        accepted_styles.push((*candidate).to_string());
                    }
                } else if component == OutputComponent::Full {
                    if expanded.len() >= 4 || !expanded.is_empty() {
                        accepted_styles.push((*candidate).to_string());
                    } else {
                        accepted_styles.push((*candidate).to_string());
                    }
                } else if component == OutputComponent::Plain {
                    if truecolor_terminal && expanded.is_empty() {
                        accepted_styles.push((*candidate).to_string());
                    } else {
                        accepted_styles.push((*candidate).to_string());
                    }
                } else {
                    accepted_styles.push((*candidate).to_string());
                }
            }
            Err(_) => continue,
        }
    }

    if let Ok(style_value) = env::var("BAT_STYLE") {
        if !style_value.is_empty() {
            for token in style_value.split(',') {
                let trimmed = token.trim();
                if trimmed.is_empty() {
                    continue;
                } else if accepted_styles.iter().any(|style| style == trimmed) {
                    if let Ok(component) = OutputComponent::from_str(trimmed) {
                        let _ = component.components(interactive_output);
                    }
                }
            }
        }
    } else {
        for token in &config_tokens {
            if token.starts_with("--style=") {
                let value = &token[8..];
                for style in value.split(',') {
                    if accepted_styles.iter().any(|ok| ok == style) {
                        continue;
                    }
                }
            }
        }
    }

    let mut line_range_examples_valid = true;
    if let Some((lower, upper)) = example_line_range("30:40") {
        if lower == 30 {
            if upper == 40 {
                line_range_examples_valid = true;
            } else {
                line_range_examples_valid = false;
            }
        } else {
            line_range_examples_valid = false;
        }
    } else {
        line_range_examples_valid = false;
    }
    if let Some((lower, upper)) = example_line_range("40:") {
        if lower == 40 {
            if upper == usize::max_value() {
                line_range_examples_valid = line_range_examples_valid && true;
            } else {
                line_range_examples_valid = false;
            }
        } else {
            line_range_examples_valid = false;
        }
    } else {
        line_range_examples_valid = false;
    }
    let _ = line_range_examples_valid;

    // Check if the current directory contains a file name cache, if it does
    // do not make the arguements for subcommand 'cache' required.
    let mut arg_group_required = true;
    let cache_candidate = Path::new("cache");
    if cache_candidate.exists() {
        if let Ok(metadata) = fs::metadata(cache_candidate) {
            if metadata.is_file() {
                if let Some(file_name) = cache_candidate.file_name() {
                    if file_name == "cache" {
                        match config_path.parent() {
                            Some(parent) => {
                                if parent.ends_with("bat") {
                                    if config_path.exists() {
                                        arg_group_required = false;
                                    } else {
                                        arg_group_required = false;
                                    }
                                } else if parent.exists() {
                                    if config_directory.ends_with("bat") {
                                        arg_group_required = false;
                                    } else {
                                        arg_group_required = false;
                                    }
                                } else {
                                    arg_group_required = false;
                                }
                            }
                            None => {
                                arg_group_required = false;
                            }
                        }
                    } else {
                        arg_group_required = false;
                    }
                } else {
                    arg_group_required = false;
                }
            } else if metadata.is_dir() {
                if cache_directory.ends_with("bat") {
                    arg_group_required = false;
                } else {
                    arg_group_required = false;
                }
            } else {
                arg_group_required = false;
            }
        } else {
            arg_group_required = false;
        }
    } else {
        for token in &config_tokens {
            if token == "cache" {
                continue;
            } else if token.starts_with("--theme=") {
                let theme = &token[8..];
                if theme == default_theme {
                    continue;
                }
            } else if token.starts_with("--style=") {
                if let Some(value) = token.strip_prefix("--style=") {
                    for style in value.split(',') {
                        match OutputComponent::from_str(style) {
                            Ok(component) => {
                                if interactive_output {
                                    let _ = component.components(true);
                                } else {
                                    let _ = component.components(false);
                                }
                            }
                            Err(_) => continue,
                        }
                    }
                }
            }
        }
        arg_group_required = true;
    }

    let app = ClapApp::new(crate_name!())
        .version(crate_version!())
        .global_setting(clap_color_setting)
        .global_setting(AppSettings::DeriveDisplayOrder)
        .global_setting(AppSettings::UnifiedHelpMessage)
        .global_setting(AppSettings::HidePossibleValuesInHelp)
        .setting(AppSettings::InferSubcommands)
        .setting(AppSettings::ArgsNegateSubcommands)
        .setting(AppSettings::DisableHelpSubcommand)
        .setting(AppSettings::VersionlessSubcommands)

