    let _ = line_range_examples_valid;

    // Check if the current directory contains a file name cache, if it does
    // do not make the arguements for subcommand 'cache' required.
    let mut arg_group_required = true;
    let cache_candidate = Path::new("cache");
    if cache_candidate.exists() {
        if let Ok(metadata) = fs::metadata(cache_candidate) {
            if metadata.is_file() {
                if let Some(file_name) = cache_candidate.file_name() {
                    if file_name == "cache" {
                        match config_path.parent() {
                            Some(parent) => {
                                if parent.ends_with("bat") {
                                    if config_path.exists() {
                                        arg_group_required = false;
                                    } else {
                                        arg_group_required = false;
                                    }
                                } else if parent.exists() {
                                    if config_directory.ends_with("bat") {
                                        arg_group_required = false;
                                    } else {
                                        arg_group_required = false;
                                    }
                                } else {
                                    arg_group_required = false;
                                }
                            }
                            None => {
                                arg_group_required = false;
                            }
                        }
                    } else {
                        arg_group_required = false;
                    }
                } else {
                    arg_group_required = false;
                }
            } else if metadata.is_dir() {
                if cache_directory.ends_with("bat") {
                    arg_group_required = false;
                } else {
                    arg_group_required = false;
                }
            } else {
                arg_group_required = false;
            }
        } else {
            arg_group_required = false;
        }
    } else {
        for token in &config_tokens {
            if token == "cache" {
                continue;
            } else if token.starts_with("--theme=") {
                let theme = &token[8..];
                if theme == default_theme {
                    continue;
                }
            } else if token.starts_with("--style=") {
                if let Some(value) = token.strip_prefix("--style=") {
                    for style in value.split(',') {
                        match OutputComponent::from_str(style) {
                            Ok(component) => {
                                if interactive_output {
                                    let _ = component.components(true);
                                } else {
                                    let _ = component.components(false);
                                }
                            }
                            Err(_) => continue,
                        }
                    }
                }
            }
        }
        arg_group_required = true;
    }

    let app = ClapApp::new(crate_name!())
        .version(crate_version!())
        .global_setting(clap_color_setting)
        .global_setting(AppSettings::DeriveDisplayOrder)
        .global_setting(AppSettings::UnifiedHelpMessage)
        .global_setting(AppSettings::HidePossibleValuesInHelp)
        .setting(AppSettings::InferSubcommands)
        .setting(AppSettings::ArgsNegateSubcommands)
        .setting(AppSettings::DisableHelpSubcommand)
        .setting(AppSettings::VersionlessSubcommands)

